@sig trait DockingAssessmentOwner_Api {
  def id: Art.BridgeId
  def dockingSample_Id : Art.PortId
  def dockingAssessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var dockingAssessment: Mining_Cargo_Transfer_Supervisor.DockingAssessment.Type = $

  def put_dockingAssessment(value : Mining_Cargo_Transfer_Supervisor.DockingAssessment.Type) : Unit = {
    Contract(
      Modifies(dockingAssessment),
      Ensures(
        dockingAssessment == value
      )
    )
    Spec {
      dockingAssessment = value
    }

    Art.putValue(dockingAssessment_Id, Mining_Cargo_Transfer_Supervisor.DockingAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class DockingAssessmentOwner_Initialization_Api (
  val id: Art.BridgeId,
  val dockingSample_Id : Art.PortId,
  val dockingAssessment_Id : Art.PortId) extends DockingAssessmentOwner_Api

@datatype class DockingAssessmentOwner_Operational_Api (
  val id: Art.BridgeId,
  val dockingSample_Id : Art.PortId,
  val dockingAssessment_Id : Art.PortId) extends DockingAssessmentOwner_Api {

  // Logika spec var representing port state for incoming data port
  @spec var dockingSample: Mining_Cargo_Transfer_Supervisor.DockingSample = $

  def get_dockingSample() : Option[Mining_Cargo_Transfer_Supervisor.DockingSample] = {
    Contract(
      Ensures(
        Res == Some(dockingSample)
      )
    )
    val value : Option[Mining_Cargo_Transfer_Supervisor.DockingSample] = Art.getValue(dockingSample_Id) match {
      case Some(Mining_Cargo_Transfer_Supervisor.DockingSample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port dockingSample.  Expecting 'Mining_Cargo_Transfer_Supervisor.DockingSample_Payload' but received ${v}")
        None[Mining_Cargo_Transfer_Supervisor.DockingSample]()
      case _ => None[Mining_Cargo_Transfer_Supervisor.DockingSample]()
    }
    return value
  }
}
